"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["49021"],{46182(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_fase.guarda_da_vaga_nao_declaravel","status":422,"titulo":"A guarda da vaga declarada n\xe3o \xe9 uma das op\xe7\xf5es aceitas"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_fase.guarda_da_vaga_nao_declaravel","requisitos":["UNI-REQ-0348"],"oQueAconteceu":["A configura\xe7\xe3o do recurso de uma fase declara uma **guarda da vaga** que n\xe3o \xe9 uma das op\xe7\xf5es aceitas (UNI-REQ-0348). A guarda da vaga diz se a vaga em disputa fica guardada at\xe9 o resultado definitivo enquanto o recurso \xe9 julgado. A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `fases[i].regraRecurso.guardaDaVaga`, em que `i` \xe9 a posi\xe7\xe3o da fase.","A mensagem da resposta diz: \\"A guarda da vaga n\xe3o \xe9 uma das op\xe7\xf5es aceitas: guardar a vaga at\xe9 o resultado definitivo ou n\xe3o guardar a vaga. Sem a guarda informada, vale guardar at\xe9 o resultado definitivo.\\" Ela n\xe3o repete o valor enviado."],"comoResolver":["Informe, em `guardaDaVaga`, um destes c\xf3digos: `ateOResultadoDefinitivo` (a vaga fica guardada at\xe9 o resultado definitivo) ou `naoGuarda` (a vaga n\xe3o fica guardada durante o recurso). Se o campo ficar em branco, vale `ateOResultadoDefinitivo`. Com inst\xe2ncia superior, s\xf3 `ateOResultadoDefinitivo` \xe9 aceito; veja [guarda com inst\xe2ncia superior](/erros/uniplus.selecao.configuracao_do_recurso_da_fase.nao_guarda_com_instancia_superior)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);